<div class="page-title"><div><h2>فروش‌ها</h2></div></div><section class="card"><div class="table-responsive"><table class="table proma-accounting-table"><thead><tr><th>قرارداد</th><th>مشتری</th><th>فروشنده</th><th>مبلغ تامین‌شده</th><th>کانال</th><th>وضعیت</th></tr></thead><tbody><?php foreach (($sales ?? []) as $sale): ?><tr><td><?= e($sale['contract_number']) ?></td><td><?= e($sale['customer_name']) ?></td><td><?= e($sale['seller_name'] ?: 'نیازمند تخصیص') ?></td><td><?= money_toman($sale['financed_amount']) ?></td><td><?= e($sale['sales_channel']) ?></td><td><?= e($sale['status']) ?></td></tr><?php endforeach; ?><?php if (empty($sales)): ?><tr><td colspan="6" class="empty">فروشی ثبت نشده است.</td></tr><?php endif; ?></tbody></table></div></section>
